"""Extract the Snowflake tables and views read by a Power Query (M) expression.

Two patterns are recognized:

* Navigation generated by the Snowflake connector::

      Source = Snowflake.Databases("acme.snowflakecomputing.com", "WH"),
      Db = Source{[Name="ANALYTICS", Kind="Database"]}[Data],
      Sch = Db{[Name="SALES", Kind="Schema"]}[Data],
      Orders = Sch{[Name="ORDERS", Kind="Table"]}[Data]

* Custom SQL passed with ``Value.NativeQuery(<database>, "SELECT ...")``: the
  objects after FROM and JOIN are reported, qualified with the database and
  schema navigated to before the query.

Names given through Power Query parameters are resolved from the model's
shared expressions. A name that can't be resolved is reported as ``{Name}``.
"""

import re
from dataclasses import dataclass

# A value in an M call or record: "string", #"quoted identifier" or identifier.
M_VALUE = r'"(?:[^"]|"")*"|#"(?:[^"]|"")*"|[A-Za-z_][\w.]*'

TOKEN_PATTERN = re.compile(
    rf"Snowflake\.Databases\(\s*(?P<server>{M_VALUE})\s*,\s*(?P<warehouse>{M_VALUE})"
    rf"|\{{\s*\[(?P<record>[^\[\]]*)\]\s*\}}"
    rf"|Value\.NativeQuery\(\s*[^,]+,\s*(?P<sql>{M_VALUE})",
)
RECORD_FIELD_PATTERN = re.compile(rf"(\w+)\s*=\s*({M_VALUE})")
PARAMETER_PATTERN = re.compile(r'^\s*("(?:[^"]|"")*")\s*meta\s*\[', re.DOTALL)

SQL_IDENTIFIER = r'"[^"]+"|[\w$]+'
SQL_TABLE_PATTERN = re.compile(
    rf"\b(?:FROM|JOIN)\s+(?P<name>(?>(?:{SQL_IDENTIFIER})(?:\s*\.\s*(?:{SQL_IDENTIFIER})){{0,2}}))(?!\s*\()",
    re.IGNORECASE,
)
SQL_CTE_PATTERN = re.compile(rf"(?:\bWITH|,)\s*({SQL_IDENTIFIER})\s+AS\s*\(", re.IGNORECASE)
SQL_PART_PATTERN = re.compile(SQL_IDENTIFIER)
SQL_NON_TABLE_KEYWORDS = {"LATERAL", "TABLE"}

M_STRING_ESCAPES = {"#(lf)": "\n", "#(cr)": "\r", "#(tab)": "\t", "#(#)": "#"}


@dataclass(frozen=True)
class SnowflakeObject:
    """A Snowflake object read by a model table.

    ``kind`` is ``Table`` or ``View`` for connector navigation, and
    ``SQL reference`` for an object named in a native SQL query (Snowflake
    doesn't say there whether it is a table or a view).
    """

    server: str | None
    warehouse: str | None
    database: str | None
    schema: str | None
    name: str | None
    kind: str
    native_sql: str | None = None


def unescape_m_string(literal: str) -> str:
    """Return the text of an M string literal such as ``"a""b#(lf)c"``."""
    text = literal[1:-1].replace('""', '"')
    for escape, character in M_STRING_ESCAPES.items():
        text = text.replace(escape, character)
    return text


def parse_parameters(shared_expressions: dict[str, str]) -> dict[str, str]:
    """Return the text values of the Power Query parameters among the shared expressions."""
    parameters = {}
    for name, expression in shared_expressions.items():
        match = PARAMETER_PATTERN.match(expression)
        if match:
            parameters[name] = unescape_m_string(match.group(1))
    return parameters


def _resolve_value(token: str, parameters: dict[str, str]) -> str:
    """Return the text of an M value, looking parameters up by name."""
    if token.startswith('"'):
        return unescape_m_string(token)
    name = unescape_m_string(token[1:]) if token.startswith("#") else token
    return parameters.get(name, f"{{{name}}}")


def _references(expression: str, name: str) -> bool:
    """Return whether the M expression refers to the query called `name`."""
    quoted = f'#"{name.replace('"', '""')}"'
    if quoted in expression:
        return True
    return re.search(rf'(?<![\w."#]){re.escape(name)}(?![\w"])', expression) is not None


def _with_referenced_queries(expression: str, shared_expressions: dict[str, str]) -> str:
    """Return the expression preceded by the shared queries it refers to, recursively.

    A model table often starts from a shared query that opens the Snowflake
    connection, so its navigation steps only make sense together.
    """
    included: list[str] = []
    pending = [expression]
    while pending:
        current = pending.pop()
        for name, shared in shared_expressions.items():
            if name not in included and shared != current and _references(current, name):
                included.append(name)
                pending.append(shared)
    referenced = [shared_expressions[name] for name in reversed(included)]
    return "\n".join([*referenced, expression])


def _sql_identifier(part: str) -> str:
    """Return a Snowflake identifier as stored: quoted keeps its case, unquoted is uppercased."""
    return part[1:-1] if part.startswith('"') else part.upper()


def extract_sql_tables(sql: str) -> list[tuple[str | None, str | None, str]]:
    """Return the (database, schema, name) of the objects after FROM and JOIN.

    Common table expressions are left out. Missing parts are None.
    """
    cte_names = {_sql_identifier(name) for name in SQL_CTE_PATTERN.findall(sql)}
    tables = []
    for match in SQL_TABLE_PATTERN.finditer(sql):
        parts = [_sql_identifier(part) for part in SQL_PART_PATTERN.findall(match.group("name"))]
        if len(parts) == 1 and (parts[0] in cte_names or parts[0] in SQL_NON_TABLE_KEYWORDS):
            continue
        database, schema, name = [None] * (3 - len(parts)) + parts
        tables.append((database, schema, name))
    return list(dict.fromkeys(tables))


def extract_snowflake_objects(
    expression: str,
    shared_expressions: dict[str, str],
) -> list[SnowflakeObject]:
    """Return the Snowflake objects read by one model table's M expression.

    Args:
        expression: The M expression of the table partition.
        shared_expressions: The model's shared queries and parameters, by name.

    Returns:
        The objects in order of appearance, without duplicates. Empty when
        the expression doesn't use the Snowflake connector.
    """
    text = _with_referenced_queries(expression, shared_expressions)
    if "Snowflake.Databases" not in text:
        return []
    parameters = parse_parameters(shared_expressions)

    objects: list[SnowflakeObject] = []
    server = warehouse = database = schema = None
    for match in TOKEN_PATTERN.finditer(text):
        if match.group("server"):
            server = _resolve_value(match.group("server"), parameters)
            warehouse = _resolve_value(match.group("warehouse"), parameters)
            database = schema = None
        elif match.group("sql"):
            sql = _resolve_value(match.group("sql"), parameters)
            tables = extract_sql_tables(sql) or [(None, None, None)]
            objects.extend(
                SnowflakeObject(
                    server,
                    warehouse,
                    sql_database or database,
                    sql_schema or schema,
                    name,
                    "SQL reference",
                    sql,
                )
                for sql_database, sql_schema, name in tables
            )
        else:
            fields = {
                key: _resolve_value(value, parameters)
                for key, value in RECORD_FIELD_PATTERN.findall(match.group("record"))
            }
            kind = fields.get("Kind")
            name = fields.get("Name")
            if kind == "Database":
                database, schema = name, None
            elif kind == "Schema":
                schema = name
            elif kind in ("Table", "View"):
                objects.append(SnowflakeObject(server, warehouse, database, schema, name, kind))
    return list(dict.fromkeys(objects))
